{
  "title": "Scholarship Applications Summary",
  "subtitle": "Overview of scholarship applications and key metrics for the board",
  "panels": [
    {"id": "p1", "kind": "kpi", "title": "Total Applications", "sql": "SELECT COUNT(*) AS total FROM scholarship_applicants", "unit": ""},
    {"id": "p2", "kind": "kpi", "title": "Approved Applications", "sql": "SELECT COUNT(*) AS approved FROM scholarship_applicants WHERE Status = 'Approved'", "unit": ""},
    {"id": "p3", "kind": "bar", "title": "Applications by District", "sql": "SELECT District, COUNT(*) AS count FROM scholarship_applicants GROUP BY 1 ORDER BY 2 DESC LIMIT 10", "x": "District", "y": ["count"]},
    {"id": "p4", "kind": "bar", "title": "Approval Rate by Category", "sql": "SELECT Category, COUNT(*) * 100.0 / NULLIF(COUNT(*),0) AS rate FROM scholarship_applicants WHERE Status = 'Approved' GROUP BY 1 ORDER BY 2 DESC", "x": "Category", "y": ["rate"], "unit": "%"},
    {"id": "p5", "kind": "table", "title": "Top 10 Schemes by Applications", "sql": "SELECT \"Name of scheme\", COUNT(*) AS count FROM scholarship_applicants GROUP BY 1 ORDER BY 2 DESC LIMIT 10"}
  ],
  "narrative": "The board received {{p1}} total scholarship applications, with {{p2}} of them approved. Applications are concentrated in specific districts, with the top district accounting for {{p3.x[0]}} applications. Approval rates vary by category, with {{p4.x[0]}} showing the highest rate at {{p4.y[0]}}%. The most popular schemes are listed in the table, with {{p5.x[0]}} leading in applications."
}

{
  "title": "Pending Scholarship Applications",
  "subtitle": "District-wise breakdown of pending scholarship cases",
  "panels": [
    {
      "id": "p1",
      "kind": "kpi",
      "title": "Total pending applications",
      "sql": "SELECT COUNT(*) AS n FROM scholarship_applicants WHERE \"Status\" = 'Pending'",
      "unit": ""
    },
    {
      "id": "p2",
      "kind": "bar",
      "title": "Pending cases by district",
      "sql": "SELECT \"District\", COUNT(*) AS pending_count FROM scholarship_applicants WHERE \"Status\" = 'Pending' GROUP BY 1 ORDER BY 2 DESC",
      "x": "District",
      "y": ["pending_count"]
    },
    {
      "id": "p3",
      "kind": "table",
      "title": "Pending application details",
      "sql": "SELECT * FROM scholarship_applicants WHERE \"Status\" = 'Pending' LIMIT 10"
    }
  ],
  "narrative": "This dashboard shows the current status of pending scholarship applications. The total number of pending cases is {{p1}}. The bar chart highlights which districts have the most pending applications, with {{p2.District}} showing the highest volume. The table lists the first 10 pending applications for detailed review."
}

{
  "title": "Child Improvement Dashboard",
  "subtitle": "Comparing baseline to endline performance by location and coach",
  "panels": [
    {
      "id": "p1",
      "kind": "kpi",
      "title": "Total children tracked",
      "sql": "SELECT COUNT(DISTINCT \"Child ID\") AS n FROM baseline",
      "unit": ""
    },
    {
      "id": "p2",
      "kind": "bar",
      "title": "Average shuttle run improvement by location",
      "sql": "SELECT \"Location\", AVG(\"Shuttle run sec\"_end - \"Shuttle run sec\"_base) AS improvement FROM (SELECT b.\"Child ID\", b.\"Location\", b.\"Shuttle run sec\" AS \"Shuttle run sec\"_base, e.\"Shuttle run sec\" AS \"Shuttle run sec\"_end FROM baseline b JOIN endline e ON b.\"Child ID\" = e.\"Child ID\") GROUP BY 1 ORDER BY 2 DESC LIMIT 10",
      "x": "Location",
      "y": ["improvement"]
    },
    {
      "id": "p3",
      "kind": "bar",
      "title": "Average sit-ups improvement by coach",
      "sql": "SELECT \"Coach\", AVG(\"Sit ups\"_end - \"Sit ups\"_base) AS improvement FROM (SELECT b.\"Coach\", b.\"Child ID\", b.\"Sit ups\" AS \"Sit ups\"_base, e.\"Sit ups\" AS \"Sit ups\"_end FROM baseline b JOIN endline e ON b.\"Child ID\" = e.\"Child ID\") GROUP BY 1 ORDER BY 2 DESC LIMIT 10",
      "x": "Coach",
      "y": ["improvement"]
    },
    {
      "id": "p4",
      "kind": "table",
      "title": "Top 10 children with greatest shuttle run improvement",
      "sql": "SELECT b.\"Child ID\", b.\"Child name\", (e.\"Shuttle run sec\" - b.\"Shuttle run sec\") AS improvement FROM baseline b JOIN endline e ON b.\"Child ID\" = e.\"Child ID\" ORDER BY improvement DESC LIMIT 10"
    }
  ],
  "narrative": "The dashboard shows {{p1}} children were tracked across locations and coaches. Average shuttle run improvements varied by location, with {{p2}} showing the most significant gains. Coaches like {{p3}} demonstrated strong performance in sit-ups improvement. The table highlights individual cases where children improved by over {{p4.improvement}} seconds in shuttle runs."
}

{
  "title": "Fitness Programme Results Summary",
  "subtitle": "Overview of programme outcomes and key metrics for the donor",
  "panels": [
    {"id": "p1", "kind": "kpi", "title": "Total children enrolled", "sql": "SELECT COUNT(*) AS n FROM (SELECT \"Child ID\" FROM baseline UNION ALL SELECT \"Child ID\" FROM endline) AS combined", "unit": ""},
    {"id": "p2", "kind": "bar", "title": "Average fitness score by location", "sql": "SELECT \"Location\", AVG(\"Shuttle run sec\") AS avg_shuttle_run, AVG(\"Sit ups\") AS avg_sit_ups FROM (SELECT * FROM baseline UNION ALL SELECT * FROM endline) AS combined GROUP BY 1 ORDER BY 2 DESC", "x": "Location", "y": ["avg_shuttle_run", "avg_sit_ups"]},
    {"id": "p3", "kind": "line", "title": "Progress in shuttle run time over time", "sql": "SELECT 'Baseline' AS period, AVG(\"Shuttle run sec\") AS avg_time FROM baseline UNION ALL SELECT 'Endline' AS period, AVG(\"Shuttle run sec\") AS avg_time FROM endline ORDER BY 1", "x": "period", "y": ["avg_time"]},
    {"id": "p4", "kind": "table", "title": "Top 10 locations with highest improvement in sit-ups", "sql": "WITH baseline_avg AS (SELECT \"Location\", AVG(\"Sit ups\") AS baseline_avg FROM baseline GROUP BY 1), endline_avg AS (SELECT \"Location\", AVG(\"Sit ups\") AS endline_avg FROM endline GROUP BY 1) SELECT b.\"Location\", b.baseline_avg, e.endline_avg, (e.endline_avg - b.baseline_avg) AS improvement FROM baseline_avg b JOIN endline_avg e ON b.\"Location\" = e.\"Location\" ORDER BY improvement DESC LIMIT 10"}
  ],
  "narrative": "The fitness programme successfully engaged {{p1}} children across various locations. On average, children demonstrated improvements in their physical fitness metrics, particularly in sit-ups, with the top 10 locations showing notable gains. The shuttle run times decreased from baseline to endline, indicating enhanced agility and speed. These results highlight the effectiveness of the programme in promoting overall physical development among participants."
}

{
  "title": "Fitness Program Results Summary",
  "subtitle": "Key metrics and trends from baseline to endline assessments",
  "panels": [
    {"id": "p1", "kind": "kpi", "title": "Total children", "sql": "SELECT COUNT(*) AS n FROM (SELECT \"Child ID\" FROM baseline UNION ALL SELECT \"Child ID\" FROM endline) t", "unit": ""},
    {"id": "p2", "kind": "bar", "title": "Average score by location", "sql": "SELECT \"Location\", AVG(\"Shuttle run sec\") AS avg_score FROM (SELECT \"Location\", \"Shuttle run sec\" FROM baseline UNION ALL SELECT \"Location\", \"Shuttle run sec\" FROM endline) t GROUP BY 1 ORDER BY 2 DESC LIMIT 20", "x": "Location", "y": ["avg_score"]},
    {"id": "p3", "kind": "line", "title": "Monthly trend in sit-ups", "sql": "SELECT month, SUM(\"Sit ups\") AS total FROM (SELECT DATE_TRUNC('month', \"DOB\") AS month, \"Sit ups\" FROM baseline UNION ALL SELECT DATE_TRUNC('month', \"DOB\") AS month, \"Sit ups\" FROM endline) t GROUP BY 1 ORDER BY 1", "x": "month", "y": ["total"]},
    {"id": "p4", "kind": "table", "title": "Top 10 locations by child count", "sql": "SELECT \"Location\", COUNT(*) AS child_count FROM (SELECT \"Location\" FROM baseline UNION ALL SELECT \"Location\" FROM endline) t GROUP BY 1 ORDER BY 2 DESC LIMIT 10"}
  ],
  "narrative": "The program tracked {{p1}} children across {{p4.n}} locations. Average shuttle run times varied by location, with {{p2.x}} showing the most improvement. Monthly sit-up trends indicate {{p3.y}} increased by {{p3.n}} over time. The top location was {{p4.x}} with {{p4.n}} participants."
}

{
  "title": "Gender Improvement Comparison",
  "subtitle": "Comparison of physical improvements between girls and boys in baseline and endline data",
  "panels": [
    {
      "id": "p1",
      "kind": "kpi",
      "title": "Avg shuttle run improvement (girls)",
      "sql": "SELECT AVG(endline.\"Shuttle run sec\" - baseline.\"Shuttle run sec\") AS improvement FROM baseline JOIN endline ON baseline.\"Child ID\" = endline.\"Child ID\" WHERE baseline.\"Gender\" = 'Female'",
      "unit": "seconds"
    },
    {
      "id": "p2",
      "kind": "kpi",
      "title": "Avg shuttle run improvement (boys)",
      "sql": "SELECT AVG(endline.\"Shuttle run sec\" - baseline.\"Shuttle run sec\") AS improvement FROM baseline JOIN endline ON baseline.\"Child ID\" = endline.\"Child ID\" WHERE baseline.\"Gender\" = 'Male'",
      "unit": "seconds"
    },
    {
      "id": "p3",
      "kind": "bar",
      "title": "Shuttle run time by gender",
      "sql": "SELECT 'Baseline' AS period, \"Gender\", AVG(\"Shuttle run sec\") AS avg_time FROM baseline GROUP BY 2 UNION ALL SELECT 'Endline' AS period, \"Gender\", AVG(\"Shuttle run sec\") AS avg_time FROM endline GROUP BY 2 ORDER BY 2, 1",
      "x": "period",
      "y": ["avg_time"]
    },
    {
      "id": "p4",
      "kind": "bar",
      "title": "Sit ups by gender",
      "sql": "SELECT 'Baseline' AS period, \"Gender\", AVG(\"Sit ups\") AS avg_situps FROM baseline GROUP BY 2 UNION ALL SELECT 'Endline' AS period, \"Gender\", AVG(\"Sit ups\") AS avg_situps FROM endline GROUP BY 2 ORDER BY 2, 1",
      "x": "period",
      "y": ["avg_situps"]
    },
    {
      "id": "p5",
      "kind": "table",
      "title": "Top 10 shuttle run improvements",
      "sql": "SELECT baseline.\"Child ID\", baseline.\"Gender\", endline.\"Shuttle run sec\" - baseline.\"Shuttle run sec\" AS improvement FROM baseline JOIN endline ON baseline.\"Child ID\" = endline.\"Child ID\" WHERE endline.\"Shuttle run sec\" < baseline.\"Shuttle run sec\" ORDER BY improvement DESC LIMIT 10"
    }
  ],
  "narrative": "Girls showed an average shuttle run improvement of {{p1}} seconds compared to {{p2}} seconds for boys. Baseline shuttle run times for girls were {{p3.n[1]}} and boys {{p3.n[3]}}, improving to {{p3.n[2]}} and {{p3.n[4]}} respectively by endline. Similar patterns appear in sit-ups: baseline averages were {{p4.n[1]}} (girls) and {{p4.n[3]}} (boys), rising to {{p4.n[2]}} and {{p4.n[4]}}. The table highlights individual cases where children improved most in shuttle run times."
}

{
  "title": "SHG Loan Insights",
  "subtitle": "Repayment status and loan purpose distribution",
  "panels": [
    {"id": "p1", "kind": "kpi", "title": "Total Loans", "sql": "SELECT COUNT(*) AS n FROM shg_loan_register", "unit": ""},
    {"id": "p2", "kind": "kpi", "title": "Overdue Loans", "sql": "SELECT COUNT(*) AS n FROM shg_loan_register WHERE \"Repayment Status\" = 'Overdue'", "unit": ""},
    {"id": "p3", "kind": "kpi", "title": "Overdue Rate", "sql": "SELECT (COUNT(CASE WHEN \"Repayment Status\" = 'Overdue' THEN 1 END) * 100.0 / NULLIF(COUNT(*), 0)) AS overdue_rate FROM shg_loan_register", "unit": "%"},
    {"id": "p4", "kind": "bar", "title": "Repayment Distribution", "sql": "SELECT \"Repayment Status\", COUNT(*) AS count FROM shg_loan_register GROUP BY 1 ORDER BY 2 DESC", "x": "Repayment Status", "y": ["count"]},
    {"id": "p5", "kind": "bar", "title": "Loan Purposes", "sql": "SELECT \"Purpose\", COUNT(*) AS count FROM shg_loan_register GROUP BY 1 ORDER BY 2 DESC", "x": "Purpose", "y": ["count"]},
    {"id": "p6", "kind": "table", "title": "Top 5 Loan Purposes", "sql": "SELECT \"Purpose\", COUNT(*) AS count FROM shg_loan_register GROUP BY 1 ORDER BY 2 DESC LIMIT 5"}
  ],
  "narrative": "The SHG loan program has issued {{p1}} total loans, with {{p2}} currently overdue ({{p3}}% of total). The repayment status distribution is visualized in {{p4}}, showing the proportion of loans in each category. The primary purposes for which loans are taken are detailed in {{p5}}, and the top five purposes are listed in {{p6}}."
}

{
  "title": "District Health Comparison",
  "subtitle": "Key health indicators across districts in Bihar, Jharkhand, and Odisha",
  "panels": [
    {
      "id": "p1",
      "kind": "kpi",
      "title": "Total districts covered",
      "sql": "SELECT COUNT(DISTINCT \"District\") AS n FROM \"district_health_factsheet\" WHERE \"District\" != 'State Total'",
      "unit": ""
    },
    {
      "id": "p2",
      "kind": "bar",
      "title": "Vaccination coverage by district",
      "sql": "SELECT \"District\", AVG(\"Children age 12-23 months fully vaccinated (%)\") AS avg_vaccinated FROM \"district_health_factsheet\" WHERE \"District\" != 'State Total' GROUP BY 1 ORDER BY 2 DESC LIMIT 20",
      "x": "District",
      "y": ["avg_vaccinated"]
    },
    {
      "id": "p3",
      "kind": "line",
      "title": "Stunting trends by survey round",
      "sql": "SELECT \"Survey Round\", AVG(\"Children under 5 years who are stunted (%)\") AS avg_stunted FROM \"district_health_factsheet\" WHERE \"District\" != 'State Total' GROUP BY 1 ORDER BY 1",
      "x": "Survey Round",
      "y": ["avg_stunted"]
    },
    {
      "id": "p4",
      "kind": "table",
      "title": "Top 10 districts by stunting rate",
      "sql": "SELECT \"District\", AVG(\"Children under 5 years who are stunted (%)\") AS stunting_rate FROM \"district_health_factsheet\" WHERE \"District\" != 'State Total' GROUP BY 1 ORDER BY 2 DESC LIMIT 10"
    }
  ],
  "narrative": "The dashboard compares key health indicators across districts in three states. {{p1}} districts are analyzed, with vaccination coverage showing significant variation ({{p2.avg_vaccinated}}). Stunting rates have shown trends across survey rounds ({{p3.avg_stunted}}), and the top 10 districts with highest stunting rates are listed ({{p4.stunting_rate}})."
}
